//! The Farming Planner's signals, thresholds and curves against upstream.
//!
//! `fixtures/farming-signals.json` is generated by `script/farming-signals-oracle.mjs` from the
//! upstream `farming-planner.js` and `farming.js`, evaluated on the save the
//! fixture itself carries. The upstream account snapshot reads a dozen systems
//! this port does not apply; with them absent the two calculators agree term for
//! term, so every assertion here compares against the upstream's own output.

use idleon_core::farming::Farm;
use idleon_core::save::import;
use serde_json::Value;

fn fixture() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../fixtures/farming-signals.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("the oracle fixture is committed"))
        .expect("the oracle fixture is JSON")
}

fn number(value: &Value, key: &str) -> f64 {
    value[key]
        .as_f64()
        .unwrap_or_else(|| panic!("{key} is a number in {value}"))
}

/// `null` is the fixture's spelling of an infinite figure.
fn optional(value: &Value, key: &str) -> f64 {
    match value.get(key) {
        None | Some(Value::Null) => f64::INFINITY,
        Some(number) => number.as_f64().expect("a fixture figure is a number"),
    }
}

/// The fixture save, imported the way a user's save is.
fn imported() -> (Farm, Value) {
    let oracle = fixture();
    let save = serde_json::to_string(&oracle["save"]).expect("the fixture save serialises");
    let imported = import(&save).expect("the fixture save imports");
    (imported.farming, oracle)
}

fn close(got: f64, expected: f64, what: &str) {
    if !expected.is_finite() {
        assert!(!got.is_finite(), "{what}: got {got}, upstream is infinite");
        return;
    }
    let scale = expected.abs().max(1.0);
    assert!(
        (got - expected).abs() <= scale * 1e-9,
        "{what}: got {got}, upstream {expected}"
    );
}

#[test]
fn the_snapshot_matches_the_upstream_account_multipliers() {
    let (farm, oracle) = imported();
    let snapshot = farm.snapshot();
    let expected = &oracle["snapshot"];
    close(
        f64::from(snapshot.farm_level),
        number(expected, "farmLevel"),
        "farm level",
    );
    close(
        snapshot.growth_rate,
        number(expected, "growthRate"),
        "growth rate",
    );
    close(
        snapshot.next_crop_common,
        number(expected, "nextCropCommon"),
        "next crop common",
    );
    close(
        snapshot.overgrowth_common,
        number(expected, "overgrowthCommon"),
        "overgrowth common",
    );
    close(
        snapshot.farming_exp,
        number(expected, "farmingExp"),
        "farming EXP",
    );
    close(
        snapshot.bean_multiplier,
        number(expected, "beanMultiplier"),
        "bean multiplier",
    );
    close(
        snapshot.crop_value_cap,
        number(expected, "cropValueCap"),
        "crop value cap",
    );
    close(
        snapshot.product_bonus,
        number(expected, "productBonus"),
        "product bonus",
    );
    close(
        snapshot.expected_vines,
        number(expected, "expectedVines"),
        "expected vines",
    );
    close(
        snapshot.plot_rank_display,
        number(expected, "plotRankDisplay"),
        "plot rank display",
    );
    close(snapshot.voting29, number(expected, "voting29"), "voting 29");
    let counts = expected["cropCounts"].as_array().expect("crop counts");
    for (index, count) in counts.iter().enumerate() {
        close(
            snapshot.crop_counts[index],
            count.as_f64().unwrap_or_default(),
            &format!("GMO count {index}"),
        );
    }
    let rank = &expected["rank"];
    let bonuses = rank["bonuses"].as_array().expect("rank bonuses");
    for (index, bonus) in bonuses.iter().enumerate() {
        close(
            snapshot.rank.bonuses[index],
            bonus.as_f64().unwrap_or_default(),
            &format!("Land Rank bonus {index}"),
        );
    }
    close(
        snapshot.rank.evolution,
        number(rank, "evolution"),
        "rank evolution",
    );
    close(
        snapshot.rank.crop_value,
        number(rank, "cropValue"),
        "rank crop value",
    );
    close(
        snapshot.rank.rank_xp,
        number(rank, "rankXp"),
        "rank rank XP",
    );
    close(
        snapshot.rank.overgrowth,
        number(rank, "overgrowth"),
        "rank overgrowth",
    );
    close(
        snapshot.rank.farming_exp,
        number(rank, "farmingExp"),
        "rank farming EXP",
    );
}

#[test]
fn the_diagnostics_match_the_upstream_signals() {
    let (farm, oracle) = imported();
    let diagnostics = farm.diagnostics(&farm.snapshot());
    let expected = &oracle["diagnostics"];
    assert_eq!(
        diagnostics.crop_count,
        number(expected, "cropCount") as u32,
        "crop count"
    );
    close(
        diagnostics.crop_value_cap,
        number(expected, "cropValueCap"),
        "crop value cap",
    );
    assert_eq!(
        diagnostics.capped_plots,
        number(expected, "cappedPlots") as usize,
        "capped plots"
    );
    assert_eq!(
        diagnostics.all_plots_capped,
        expected["allPlotsCapped"].as_bool().expect("a boolean"),
        "all plots capped"
    );
    assert_eq!(
        diagnostics.ordinary_growth_at_active_cap,
        expected["ordinaryGrowthAtActiveCap"]
            .as_bool()
            .expect("a boolean"),
        "ordinary growth at the active cap"
    );
    assert_eq!(
        diagnostics.medal_plot_count,
        number(expected, "medalPlotCount") as usize,
        "medal plots"
    );
    assert_eq!(
        diagnostics.guaranteed_evolution_plots,
        number(expected, "guaranteedEvolutionPlots") as usize,
        "guaranteed evolution plots"
    );
    assert_eq!(
        diagnostics.unspent_rank_points,
        number(expected, "unspentRankPoints") as u32,
        "unspent rank points"
    );
    assert_eq!(
        diagnostics.fifth_column_max,
        number(expected, "fifthColumnMax") as u32,
        "fifth column max"
    );
    let counts = expected["gmoCounts"].as_array().expect("GMO counts");
    for (index, count) in counts.iter().enumerate() {
        close(
            diagnostics.gmo_counts[index],
            count.as_f64().unwrap_or_default(),
            &format!("GMO count {index}"),
        );
    }
}

#[test]
fn the_gmo_thresholds_are_the_upstream_thresholds() {
    assert_eq!(
        idleon_core::farming::data().gmo_thresholds,
        [200.0, 1_000.0, 2_500.0, 10_000.0, 100_000.0]
    );
    let (farm, _) = imported();
    // The save's 260 crops cross four of the five thresholds.
    assert_eq!(
        farm.snapshot().crop_counts,
        [260.0, 259.0, 257.0, 250.0, 160.0]
    );
    assert_eq!(
        farm.crop_threshold_counts(),
        farm.snapshot().crop_counts,
        "the counts are the ones the multipliers read"
    );
}

#[test]
fn the_growth_breakpoints_match_the_upstream_rows() {
    let (farm, oracle) = imported();
    let rows = farm.growth_breakpoints(&farm.snapshot());
    let expected = oracle["growthBreakpoints"].as_array().expect("rows");
    assert_eq!(rows.len(), expected.len());
    for (row, expected) in rows.iter().zip(expected) {
        assert_eq!(
            row.family,
            number(expected, "familyId") as usize,
            "family id"
        );
        assert_eq!(row.name, expected["name"].as_str().expect("a name"));
        close(
            row.requirement,
            number(expected, "requirement"),
            "requirement",
        );
        close(
            row.raw_seconds,
            number(expected, "rawSeconds"),
            "raw seconds",
        );
        close(
            row.active_seconds,
            number(expected, "activeSeconds"),
            "active seconds",
        );
        close(
            row.one_second_rate,
            optional(expected, "oneSecondRate"),
            "one-second rate",
        );
        assert_eq!(
            row.at_active_cap,
            expected["atActiveCap"].as_bool().expect("a boolean"),
            "{} at the active cap",
            row.name
        );
        assert_eq!(
            row.medal_fixed,
            expected["medalFixed"].as_bool().expect("a boolean"),
            "{} medal cycle",
            row.name
        );
    }
}

#[test]
fn every_plots_metrics_match_the_upstream_plot_metrics() {
    let (farm, oracle) = imported();
    let snapshot = farm.snapshot();
    let expected = oracle["plots"].as_array().expect("plots");
    assert_eq!(expected.len(), idleon_core::farming::PLOTS);
    for (index, expected) in expected.iter().enumerate() {
        let metric = farm.plot_metrics_with(index, &snapshot);
        let what = format!("plot {}", index + 1);
        close(
            metric.crop_id as f64,
            number(expected, "cropId"),
            &format!("{what} crop"),
        );
        close(
            metric.growth_requirement,
            number(expected, "growthRequirement"),
            &format!("{what} growth requirement"),
        );
        close(
            metric.growth_seconds,
            optional(expected, "growthSeconds"),
            &format!("{what} growth seconds"),
        );
        close(
            metric.next_crop_chance,
            number(expected, "nextCropChance"),
            &format!("{what} evolution chance"),
        );
        close(
            metric.next_overgrowth_chance,
            number(expected, "nextOvergrowthChance"),
            &format!("{what} overgrowth chance"),
        );
        close(
            metric.farming_exp,
            number(expected, "farmingExp"),
            &format!("{what} farming EXP"),
        );
        close(
            metric.rank_xp,
            number(expected, "rankXp"),
            &format!("{what} rank XP"),
        );
        close(
            metric.rank_requirement,
            number(expected, "rankRequirement"),
            &format!("{what} rank requirement"),
        );
        let value = &expected["cropValue"];
        close(
            metric.crop_value.base,
            number(value, "base"),
            &format!("{what} crop value base"),
        );
        close(
            metric.crop_value.raw,
            number(value, "raw"),
            &format!("{what} crop value raw"),
        );
        close(
            metric.crop_value.cap,
            number(value, "cap"),
            &format!("{what} crop value cap"),
        );
        close(
            metric.crop_value.value,
            number(value, "value"),
            &format!("{what} crop value"),
        );
        assert_eq!(
            metric.crop_value.capped,
            value["capped"].as_bool().expect("a boolean"),
            "{what} capped"
        );
        close(
            metric.crop_value.expected,
            number(value, "expected"),
            &format!("{what} expected value"),
        );
        close(
            metric.crop_value.expected_harvest,
            number(value, "expectedHarvest"),
            &format!("{what} expected harvest"),
        );
    }
}

#[test]
fn every_plots_curve_matches_the_upstream_curve() {
    let (farm, oracle) = imported();
    let snapshot = farm.snapshot();
    let expected = oracle["curves"].as_array().expect("curves");
    assert_eq!(expected.len(), idleon_core::farming::PLOTS);
    for expected in expected {
        let index = number(expected, "plotIdx") as usize;
        let curve = farm.overgrowth_curve(index, &snapshot);
        let what = format!("plot {} curve", index + 1);
        close(
            f64::from(curve.current_og),
            number(expected, "currentOg"),
            &format!("{what} current OG"),
        );
        close(
            curve.cycle_seconds,
            optional(expected, "cycleSeconds"),
            &format!("{what} cycle"),
        );
        close(
            f64::from(curve.best.target),
            number(expected, "bestTargetOg"),
            &format!("{what} best target"),
        );
        let rows = expected["rows"].as_array().expect("curve rows");
        assert_eq!(curve.rows.len(), rows.len(), "{what} row count");
        for (row, expected) in curve.rows.iter().zip(rows) {
            let cells = expected.as_array().expect("a curve row");
            let target = cells[0].as_f64().expect("a target");
            close(
                f64::from(row.target),
                target,
                &format!("{what} OG {target} target"),
            );
            close(
                row.reward,
                cells[1].as_f64().expect("a reward"),
                &format!("{what} OG {target} reward"),
            );
            close(
                row.repeat_seconds,
                cells[2].as_f64().unwrap_or(f64::INFINITY),
                &format!("{what} OG {target} repeat seconds"),
            );
            close(
                row.long_run_rate,
                cells[3].as_f64().unwrap_or(f64::INFINITY),
                &format!("{what} OG {target} long-run rate"),
            );
            close(
                row.eta_from_current,
                cells[4].as_f64().unwrap_or(f64::INFINITY),
                &format!("{what} OG {target} ETA"),
            );
        }
    }
}

#[test]
fn the_crop_scientist_rows_match_the_upstream_table() {
    let (farm, oracle) = imported();
    let table = farm.crop_scientist();
    let expected = oracle["cropScientist"].as_array().expect("rows");
    assert_eq!(table.rows.len(), expected.len());
    assert_eq!(table.unlocked(), expected.len(), "every gate is owned");
    for (row, expected) in table.rows.iter().zip(expected) {
        assert_eq!(row.id, number(expected, "id") as usize, "row id");
        assert!(row.unlocked, "{} is gated", row.name);
        close(row.value, number(expected, "value"), row.name);
    }
}
